"""FN6 DR4 seal (SEAL_CRITERIA.md): writes SEALED_PREDICTION_DR4.md from fn6_wb.json and its SHA-256. Reads only; recomputes nothing.
kappa = 1/2 FITTED; not theory closed.
"""
import hashlib
import json
import math
import os

HERE = os.path.dirname(os.path.abspath(__file__))
SIG_REG = 0.0276
S_LIST = ("1.0", "2.0", "3.0", "5.0", "7.0", "10.0", "15.0", "20.0", "30.0")


def main():
    d = json.load(open(os.path.join(HERE, "fn6_wb.json")))
    L = ["# FN6 sealed wide-binary prediction for Gaia DR4", "",
         "Sealed 2026-11-04, before any DR4 data, under `SEAL_CRITERIA.md`. Generated by `fn6s_seal.py` from `fn6_wb.json` (FN6 run 9fd0447628); "
         "the SHA-256 of this file is in `SEALED_PREDICTION_DR4.sha256`. Separate from `prep_2026/gaia_dr4_prep/PREREGISTRATION_DR4.md`, CW1's seal and the D2 note, "
         "none of which is edited. These are predictions of FN6's window points (a screening length L(M) = L_MW (M / 6e10 Msun)^p, form R), a description and not a derivation. "
         "kappa = 1/2 FITTED; not theory closed.", "",
         f"DR4 pipeline: the one CW1 used, SHA-256 `{d['pipeline_sha256']}`. Registered error 0.0276 (FN2 row (a)).", "",
         "## Decision rule (frozen in SEAL_CRITERIA.md)",
         "sigma_tot = sqrt(0.0276^2 + spread^2). EXCLUDED if abs(gamma_hat - gamma_inf) > 3 sigma_tot; CONSISTENT if <= 2 sigma_tot; TENSION otherwise. "
         "The window is EXCLUDED on a footing only if every point is.", ""]
    for foot in ("canonical", "alt"):
        pipe = d["pipeline"][foot]
        L.append(f"## {foot}")
        L.append(f"Newton through the same pipeline: gamma_inf {pipe['N']['gamma_inf']:.4f} (spread {pipe['N']['spread']:.4f}).")
        L.append("")
        L.append("| (p, L_MW kpc) | L(1 Msun) pc | L / r_M | gamma_r at " + ", ".join(f"{float(s):g}" for s in S_LIST) + " kAU | DR4 gamma_inf | spread | sigma_tot | CONSISTENT band | EXCLUDED outside |")
        L.append("|---|---|---|---|---|---|---|---|---|")
        for key, c in d["curves"][foot].items():
            pp = pipe[key]
            st = math.sqrt(SIG_REG ** 2 + pp["spread"] ** 2)
            g = pp["gamma_inf"]
            gr = ", ".join(f"{c['gamma_r_at_s_kAU'][s]:.4f}" for s in S_LIST)
            L.append(f"| ({key.replace('|', ', ')}) | {c['L_1Msun_pc']:.4f} | {c['sigma_rM']:.2f} | {gr} | {g:.4f} | {pp['spread']:.4f} | {st:.4f} | "
                     f"{g - 2 * st:.4f} - {g + 2 * st:.4f} | < {g - 3 * st:.4f} or > {g + 3 * st:.4f} |")
        L.append("")
    L.append("kappa = 1/2 FITTED; not theory closed.")
    text = "\n".join(L) + "\n"
    out = os.path.join(HERE, "SEALED_PREDICTION_DR4.md")
    open(out, "w").write(text)
    h = hashlib.sha256(text.encode()).hexdigest()
    open(os.path.join(HERE, "SEALED_PREDICTION_DR4.sha256"), "w").write(f"{h}  SEALED_PREDICTION_DR4.md\n")
    print("sealed", h)


if __name__ == "__main__":
    main()
